// out of discovery only when no published version remains.
func (q *Queries) ListPublishedPromptVersions(ctx context.Context, arg ListPublishedPromptVersionsParams) ([]MarketplacePromptVersion, error) {
	rows, err := q.db.Query(ctx, listPublishedPromptVersions, arg.Kind, arg.Query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MarketplacePromptVersion{}
	for rows.Next() {
		var i MarketplacePromptVersion
		if err := rows.Scan(
			&i.ID,
			&i.SeriesID,
			&i.Kind,
			&i.Version,
			&i.SourceWorkspaceID,
			&i.SourceType,
			&i.SourceID,
			&i.PublisherUserID,
			&i.PublisherDisplayName,
			&i.Content,
			&i.ContentSha256,
			&i.Name,
			&i.Summary,
			&i.Audience,
			&i.Categories,
			&i.LicenseCode,
			&i.UsageNotes,
			&i.Companions,
			&i.State,
			&i.Visibility,
			&i.ScannerRevision,
			&i.ScanResult,
			&i.ScannedAt,
			&i.IdempotencyKey,
			&i.PublishedAt,
			&i.WithdrawnAt,
			&i.WithdrawnBy,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockPromptSeries = `-- name: LockPromptSeries :many
SELECT id FROM marketplace_prompt_version WHERE series_id = $1 FOR UPDATE
`

// Series-level lock for version assignment. Locks every row of the series so a
// concurrent publish of the same asset serialises behind this one.
func (q *Queries) LockPromptSeries(ctx context.Context, seriesID pgtype.UUID) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, lockPromptSeries, seriesID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []pgtype.UUID{}
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const nextPromptSeriesVersion = `-- name: NextPromptSeriesVersion :one
SELECT COALESCE(MAX(version), 0)::int + 1 AS next_version
FROM marketplace_prompt_version
WHERE series_id = $1
`

// Next version number in a series. Called while the series' published rows are
// locked by LockPromptSeries, so the read cannot slide under a concurrent
// publish; the unique index on (series_id, version) is the second line.
func (q *Queries) NextPromptSeriesVersion(ctx context.Context, seriesID pgtype.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, nextPromptSeriesVersion, seriesID)
	var next_version int32
	err := row.Scan(&next_version)
	return next_version, err
}

